  function fill(value){cfg={...value};$('assistant-case').value=cfg.case||'custom';$('assistant-bbox').value=cfg.bbox.join(',');$('assistant-start').value=cfg.start;$('assistant-end').value=cfg.end;$('assistant-source').value=cfg.source||'joint';$('assistant-metric').value=cfg.metric||'density';$('assistant-distance').value=cfg.distance_km||2;$('assistant-gap').value=cfg.gap_days??1;describe();}
  function readForm(){const start=$('assistant-start').value,end=$('assistant-end').value,source=$('assistant-source').value;return {...cfg,case:$('assistant-case').value==='custom'?undefined:$('assistant-case').value,bbox:$('assistant-bbox').value.split(',').map(Number),start,end,as_of:end,year:Number(start.slice(0,4)),month:Number(start.slice(5,7)),day:cfg.day>=start&&cfg.day<=end?cfg.day:start,source,series:source===MODIS?'modis':source===VIIRS?'viirs-snpp':'joint',metric:$('assistant-metric').value,distance_km:Number($('assistant-distance').value),gap_days:Number($('assistant-gap').value)};}
