    const Heat=window.FireAtlasMap.install(L);const item={map,tiles,heat:new Heat(),marks:L.layerGroup().addTo(map),selection:L.layerGroup().addTo(map),notes:L.layerGroup().addTo(map),boundary:L.layerGroup().addTo(map),overlay:null};
