  function fit(){if(!maps.length)return;synchronizing=true;try{const first=maps[0].map;first.fitBounds([[cfg.bbox[1],cfg.bbox[0]],[cfg.bbox[3],cfg.bbox[2]]],{padding:[24,30],animate:false});maps.slice(1).forEach(x=>x.map.setView(first.getCenter(),first.getZoom(),{animate:false,reset:true}));}finally{synchronizing=false;}}
