      text.append(el('strong',c.title.split(' · ')[0]),el('span',c.start+' → '+c.end+' UTC'),el('small',c.summary?count(c.summary.eligible_unique_detections)+' replay detections':'Saved archive study'),indicator);button.append(text);button.addEventListener('click',()=>loadStudy(caseContext(c)));
      card.append(button,window.FireAtlasLocation.detail('case:'+c.id,window.FireAtlasLocation.area(c.bbox),c.incident?window.FireAtlasLocation.point([c.incident.longitude,c.incident.latitude]):window.FireAtlasLocation.bounds(c.bbox),c.incident?'Incident reference':'Study boundary'));
