  function studyProblem(value){const invalid=FireAtlasContext.normalize({...value,bbox:Array.isArray(value.bbox)?value.bbox.join(','):value.bbox}).errors;if(invalid.length)return 'Incoming selection retained: '+invalid.join('. ')+'. Edit the study settings to apply a valid selection.';if(!['joint','modis','viirs-snpp'].includes(value.series))return 'Detailed comparison supports authentic MODIS/S-NPP standard products. Choose that cohort explicitly.';const b=value.bbox;if(!Array.isArray(b)||b.length!==4||!b.every(Number.isFinite)||b[0]<-180||b[2]>180||b[1]<-86||b[3]>86||b[0]>=b[2]||b[1]>=b[3])return 'Enter a valid boundary as west, south, east, north in degrees.';const first=Date.parse(value.start+'T00:00:00Z'),last=Date.parse(value.end+'T00:00:00Z');if(!Number.isFinite(first)||!Number.isFinite(last)||last<first||last-first>30*86400000)return 'The map needs an ordered window of at most 31 UTC days. Use the first-month action or choose a shorter interval.';return null;}
